121	/****************************************************************************
122	 * Private Functions - Clock and Reset Control
123	 ****************************************************************************/
124	
125	static void gmac_clock_enable(void)
126	{
127	  uint32_t reg;
128	
129	  /* Enable GMAC0 clocks: clk_500m_eth0 + clk_axi4_eth0 */
130	
131	  reg = getreg32(REG_CLK_EN_0);
132	  reg |= CLK_EN_ETH0_500M | CLK_EN_ETH0_AXI4;
133	  putreg32(reg, REG_CLK_EN_0);
134	
135	  /* Deassert clock-domain resets used by the CVITEK clock-reset
136	   * controller.  Do not confuse these IDs with the main reset-controller
137	   * IDs at 0x03003000.
138	   */
139	
140	  clk_reset_deassert(CLK_RST_500M_ETH0);
141	  clk_reset_deassert(CLK_RST_AXI_ETH0);
142	
143	  /* Release the main reset-controller lines for GMAC and internal EPHY.
144	   * The Linux CVITEK reset driver deasserts by setting the corresponding
145	   * bit in the reset bank.
146	   */
147	
148	  reset_assert(RST_ETH0);
149	  reset_assert(RST_ETHPHY);
150	  reset_assert(RST_ETHPHYRST_APB);
151	  up_udelay(10);
152	  reset_deassert(RST_ETHPHYRST_APB);
153	  reset_deassert(RST_ETHPHY);
154	  reset_deassert(RST_ETH0);
155	  up_udelay(10);
156	
157	  syslog(LOG_INFO, "sg2000_eth: GMAC clocks enabled, CLK_EN_0=0x%08" PRIX32
158	         " RESET0=0x%08" PRIX32 " RESET3=0x%08" PRIX32 "\n",
159	         getreg32(REG_CLK_EN_0), getreg32(REG_RESET_BANK(0)),
160	         getreg32(REG_RESET_BANK(3)));
161	}
