163	/****************************************************************************
164	 * Private Functions - DMA Software Reset
165	 ****************************************************************************/
166	
167	static int dma_soft_reset(uintptr_t gmac_base)
168	{
169	  uint32_t val;
170	  int timeout = 100000;
171	
172	  val = getreg32(gmac_base + DMA_BUS_MODE);
173	  syslog(LOG_INFO, "sg2000_eth: DMA reset begin bus_mode=0x%08" PRIX32
174	         "\n", val);
175	  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);
176	
177	  do
178	    {
179	      val = getreg32(gmac_base + DMA_BUS_MODE);
180	      if (!(val & DMA_SFT_RESET))
181	        {
182	          return 0;
183	        }
184	
185	      up_udelay(10);
186	    }
187	  while (--timeout > 0);
188	
189	  syslog(LOG_ERR, "sg2000_eth: DMA reset timeout bus_mode=0x%08" PRIX32
190	         " hw_feature0=0x%08" PRIX32 "\n",
191	         getreg32(gmac_base + DMA_BUS_MODE),
192	         getreg32(gmac_base + GMAC_HW_FEATURE0));
193	  return -1;
194	}
