411	/****************************************************************************
412	 * Name: ephy_full_tuning
413	 *
414	 * Description:
415	 *   Run the full CV182XA analog tuning sequence via APB, then switch back
416	 *   to MDIO control.  Matches Linux cv182xa_phy_config_init().
417	 *   MUST be called AFTER MDIO is confirmed operational, as it accesses
418	 *   internal pages and starts auto-negotiation which can interfere with
419	 *   MDIO if run before the MDIO interface is active.
420	 *
421	 ****************************************************************************/
422	
423	static void ephy_full_tuning(uintptr_t phy_base, uintptr_t phy_top)
424	{
425	  /* ephy_full_analog_init expects APB mode; caller ensures MDIO is working
426	   * before we switch to APB for tuning.
427	   */
428	
429	  putreg32(0x0001, phy_top + 0x4);
430	  ephy_full_analog_init(phy_base, phy_top);
431	
432	  /* ephy_full_analog_init ends with:
433	   *   page 0 + autoneg start (0x090e) + force full-duplex
434	   * Switch control back to MDIO so the GMAC can manage the PHY.
435	   */
436	
437	  putreg32(0x0000, phy_top + 0x4);
438	  up_mdelay(10);
439	
440	  syslog(LOG_INFO, "sg2000_eth: EPHY full tuning done, top=0x%08" PRIX32
441	         " sel=0x%08" PRIX32 "\n",
442	         getreg32(phy_top), getreg32(phy_top + 0x4));
443	}
444	
445	/* SG2000/CV181x uses the TRM (Technical Reference Manual) Chapter 18
446	 * legacy GMAC MDIO layout at offsets 0x10/0x14.  The standard DWMAC4
447	 * MDIO controller at 0x200/0x204 is not functional on this silicon.
448	 */
449	
450	static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
451	{
452	  uint32_t cmd;
453	  int timeout = 10000;
454	
455	  do
456	    {
457	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
458	            LEGACY_GMAC_MDIO_BUSY))
459	        {
460	          break;
461	        }
462	
463	      up_udelay(1);
464	    }
465	  while (--timeout > 0);
466	
467	  if (timeout <= 0)
468	    {
469	      return 0xffff;
470	    }
471	
472	  putreg32(0, gmac_base + LEGACY_GMAC_MDIO_DATA);
473	
474	  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
475	        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
476	        LEGACY_GMAC_MDIO_CR_250_300M | LEGACY_GMAC_MDIO_BUSY;
477	  putreg32(cmd, gmac_base + LEGACY_GMAC_MDIO_ADDR);
478	
479	  timeout = 10000;
480	  do
481	    {
482	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
483	            LEGACY_GMAC_MDIO_BUSY))
484	        {
485	          return getreg32(gmac_base + LEGACY_GMAC_MDIO_DATA) & 0xffff;
486	        }
487	
488	      up_udelay(1);
489	    }
490	  while (--timeout > 0);
491	
492	  return 0xffff;
493	}
494	
495	static void mdio_write(uintptr_t gmac_base, int phy_addr, int reg,
496	                       uint16_t data)
497	{
498	  uint32_t cmd;
499	  int timeout = 10000;
500	
501	  putreg32(data, gmac_base + LEGACY_GMAC_MDIO_DATA);
502	  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
503	        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
504	        LEGACY_GMAC_MDIO_CR_250_300M | LEGACY_GMAC_MDIO_WRITE |
505	        LEGACY_GMAC_MDIO_BUSY;
506	  putreg32(cmd, gmac_base + LEGACY_GMAC_MDIO_ADDR);
507	
508	  do
509	    {
510	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
511	            LEGACY_GMAC_MDIO_BUSY))
512	        {
513	          break;
514	        }
515	
516	      up_udelay(1);
517	    }
518	  while (--timeout > 0);
519	}
520	
521	static int mdio_verify_phy(uintptr_t gmac_base)
522	{
523	  uint16_t id1 = mdio_read(gmac_base, 0, 2);
524	  uint16_t id2 = mdio_read(gmac_base, 0, 3);
525	  uint32_t phy_id = ((uint32_t)id1 << 16) | id2;
526	
527	  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO probe phy_id=0x%08"
528	         PRIX32 "\n", phy_id);
529	
530	  if (id1 == 0xffff || id2 == 0xffff)
531	    {
532	      syslog(LOG_ERR, "sg2000_eth: TRM legacy MDIO timeout reading "
533	             "PHY ID\n");
534	      return -ENODEV;
535	    }
536	
537	  if (phy_id != CVITEK_PHY_ID)
538	    {
539	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
540	             " (expected 0x%08" PRIX32 ")\n", phy_id,
541	             (uint32_t)CVITEK_PHY_ID);
542	    }
543	
544	  return OK;
545	}
