827	/****************************************************************************
828	 * Private Functions - Doorbell Helpers
829	 ****************************************************************************/
830	
831	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
832	{
833	  uint32_t tail = priv->tx_desc_phys +
834	                  priv->tx_cur * sizeof(struct sg2000_dma_desc_s);
835	
836	  syslog(LOG_INFO,
837	         "sg2000_eth: tx_doorbell tx_cur=%u desc_phys=0x%08" PRIX32
838	         " tail=0x%08" PRIX32 "\n",
839	         priv->tx_cur, priv->tx_desc_phys, tail);
840	
841	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_END_ADDR);
842	}
843	
844	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
845	{
846	  uint32_t tail = priv->rx_desc_phys +
847	                  priv->rx_cur * sizeof(struct sg2000_dma_desc_s);
848	
849	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_END_ADDR);
850	}
