852	/****************************************************************************
853	 * Private Functions - Hardware Transmit
854	 ****************************************************************************/
855	
856	static int hw_transmit(struct sg2000_eth_priv_s *priv,
857	                       const uint8_t *data, int len)
858	{
859	  unsigned int idx = priv->tx_cur;
860	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
861	  irqstate_t flags;
862	
863	  /* Diagnostic: log TX attempt */
864	
865	  syslog(LOG_INFO,
866	         "sg2000_eth: hw_transmit idx=%u len=%d des0_before=0x%08" PRIX32 "\n",
867	         idx, len, desc->des0);
868	
869	  /* Check if the ring is full */
870	
871	  if (desc->des0 & DESC_OWN)
872	    {
873	      syslog(LOG_ERR,
874	             "sg2000_eth: TX ring full! idx=%u des0=0x%08" PRIX32 "\n",
875	             idx, desc->des0);
876	      return -EBUSY;
877	    }
878	
879	  /* Copy data to DMA TX buffer */
880	
881	  memcpy(priv->tx_buf[idx], data, len);
882	
883	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
884	  desc->des1 = len;
885	
886	  /* OWN | First Segment | Last Segment | Interrupt on Completion */
887	
888	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
889	               (len & RX_DESC_FL_MASK);
890	
891	  flags = up_irq_save();
892	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
893	
894	  /* Memory barrier: ensure descriptor is visible to DMA engine */
895	
896	  __asm__ volatile ("fence w,w" ::: "memory");
897	
898	  /* Diagnostic: dump descriptor and DMA regs after submission */
899	
900	  syslog(LOG_INFO,
901	         "sg2000_eth: hw_transmit done idx=%u "
902	         "des0=0x%08" PRIX32 " des1=0x%08" PRIX32 " "
903	         "des2=0x%08" PRIX32 " des3=0x%08" PRIX32 " "
904	         "DMA_STAT=0x%08" PRIX32 " TX_CTL=0x%08" PRIX32 "\n",
905	         idx,
906	         priv->tx_desc[idx].des0,
907	         priv->tx_desc[idx].des1,
908	         priv->tx_desc[idx].des2,
909	         priv->tx_desc[idx].des3,
910	         getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_STATUS),
911	         getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL));
912	
913	  tx_doorbell(priv);
914	  up_irq_restore(flags);
915	
916	  return 0;
917	}
918	
919	/****************************************************************************
920	 * Private Functions - TX Cleanup (called from ISR on TX complete)
921	 ****************************************************************************/
922	
923	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
924	{
925	  irqstate_t flags = up_irq_save();
926	  int cleaned = 0;
927	
928	  while (priv->tx_dirty != priv->tx_cur)
929	    {
930	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
931	
932	      if (desc->des0 & DESC_OWN)
933	        {
934	          /* Still owned by DMA, stop */
935	
936	          break;
937	        }
938	
939	      /* Check for TX errors */
940	
941	      if (desc->des0 & TX_DESC_ES)
942	        {
943	          nerr("ERROR: TX error, status=0x%08" PRIX32 "\n", desc->des0);
944	        }
945	
946	      /* Free the netpkt if we have one tracked for this slot */
947	
948	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
949	        {
950	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
951	          priv->tx_pkt[priv->tx_dirty] = NULL;
952	
953	          /* Notify upper half that TX is done */
954	
955	          netdev_lower_txdone(&priv->dev);
956	        }
957	
958	      cleaned++;
959	
960	      /* Move to next descriptor */
961	
962	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
963	    }
964	
965	  if (cleaned > 0)
966	    {
967	      syslog(LOG_INFO,
968	             "sg2000_eth: tx_cleanup freed=%d tx_dirty=%u tx_cur=%u\n",
969	             cleaned, priv->tx_dirty, priv->tx_cur);
970	    }
971	
972	  up_irq_restore(flags);
973	}
974	
975	/****************************************************************************
976	 * Private Functions - ISR
977	 ****************************************************************************/
978	
979	static int sg2000_eth_isr(int irq, void *context, void *arg)
980	{
981	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
982	  uintptr_t base = priv->gmac_base;
983	  uintptr_t dma = base + DMA_CHAN_BASE;
984	  uint32_t status;
985	  uint32_t intr_en;
986	  uint32_t mac;
987	
988	  /* Clear MAC interrupts */
989	
990	  mac = getreg32(base + GMAC_INT_STATUS);
991	  if (mac)
992	    {
993	      putreg32(mac, base + GMAC_INT_STATUS);
994	    }
995	
996	  /* Read DMA channel status (only enabled interrupts) */
997	
998	  intr_en = getreg32(dma + DMA_CHAN_INTR_ENA);
999	  status = getreg32(dma + DMA_CHAN_STATUS) & intr_en;
1000	
1001	  /* Diagnostic: log every ISR entry with status */
1002	
1003	  syslog(LOG_INFO,
1004	         "sg2000_eth: ISR dma_status=0x%08" PRIX32 " tx_cur=%u tx_dirty=%u\n",
1005	         status, priv->tx_cur, priv->tx_dirty);
1006	
1007	  if (!status)
1008	    {
1009	      return OK;
1010	    }
1011	
1012	  /* Write-1-to-clear the status bits */
1013	
1014	  putreg32(status, dma + DMA_CHAN_STATUS);
1015	
1016	  if (status & DMA_STATUS_NIS)
1017	    {
1018	      /* Normal interrupt */
1019	
1020	      if (status & DMA_STATUS_RI)
1021	        {
1022	          /* RX complete: notify upper half that packets are ready.
1023	           * The upper half will call our receive() callback to get them.
1024	           */
1025	
1026	          netdev_lower_rxready(&priv->dev);
1027	        }
1028	
1029	      if (status & DMA_STATUS_TI)
1030	        {
1031	          /* TX complete: cleanup descriptors and notify upper half */
1032	
1033	          tx_cleanup(priv);
1034	        }
1035	    }
1036	
1037	  if (status & DMA_STATUS_AIS)
1038	    {
1039	      /* Abnormal interrupt */
1040	
1041	      nerr("ERROR: DMA Abnormal: 0x%08" PRIX32 "\n", status);
1042	
1043	      if (status & DMA_STATUS_RBU)
1044	        {
1045	          nerr("ERROR: RX Buffer Unavailable\n");
1046	        }
1047	
1048	      if (status & DMA_STATUS_TPS)
1049	        {
1050	          nerr("ERROR: TX Process Stopped\n");
1051	        }
1052	
1053	      if (status & DMA_STATUS_FBE)
1054	        {
1055	          nerr("ERROR: Fatal Bus Error\n");
1056	        }
1057	    }
1058	
1059	  return OK;
1060	}
