1062	/****************************************************************************
1063	 * Name: netdriver_ifup
1064	 *
1065	 * Description:
1066	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1067	 *
1068	 ****************************************************************************/
1069	
1070	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1071	{
1072	  FAR struct sg2000_eth_priv_s *priv =
1073	      (FAR struct sg2000_eth_priv_s *)dev;
1074	  int ret;
1075	
1076	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1077	
1078	  /* Ensure GMAC clocks and resets are configured */
1079	
1080	  gmac_clock_enable();
1081	
1082	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1083	
1084	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1085	
1086	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1087	  up_mdelay(10);
1088	
1089	  ret = mdio_verify_phy(priv->gmac_base);
1090	  if (ret < 0)
1091	    {
1092	      nerr("ERROR: TRM legacy MDIO PHY not responding: %d\n", ret);
1093	      return ret;
1094	    }
1095	
1096	  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO operational "
1097	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1098	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_ADDR),
1099	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_DATA));
1100	
1101	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1102	
1103	  ret = phy_config_init(priv);
1104	  if (ret < 0)
1105	    {
1106	      nerr("ERROR: PHY init failed: %d\n", ret);
1107	      return ret;
1108	    }
1109	
1110	  ret = dma_soft_reset(priv->gmac_base);
1111	  if (ret < 0)
1112	    {
1113	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1114	             "diagnostics: %d\n", ret);
1115	      return ret;
1116	    }
1117	
1118	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1119	    {
1120	      ret = alloc_dma(priv);
1121	      if (ret < 0)
1122	        {
1123	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1124	          return ret;
1125	        }
1126	    }
1127	
1128	  init_desc_and_dma(priv);
1129	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1130	  start_mac_and_dma(priv);
1131	  rx_doorbell(priv);
1132	
1133	  up_enable_irq(priv->irq);
1134	  netdev_lower_carrier_on(dev);
1135	
1136	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1137	         priv->speed, priv->duplex ? "Full" : "Half");
1138	
1139	  /* Diagnostic: dump post-ifup register state */
1140	
1141	  syslog(LOG_INFO,
1142	         "sg2000_eth: ifup regs "
1143	         "MAC_CONF=0x%08" PRIX32 " "
1144	         "TX_CTL=0x%08" PRIX32 " RX_CTL=0x%08" PRIX32 " "
1145	         "DMA_STAT=0x%08" PRIX32 " INTR_EN=0x%08" PRIX32 "\n",
1146	         getreg32(priv->gmac_base + GMAC_CONFIG),
1147	         getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL),
1148	         getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL),
1149	         getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_STATUS),
1150	         getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_INTR_ENA));
1151	
1152	  return OK;
1153	}
1154	
1155	/****************************************************************************
1156	 * Name: netdriver_ifdown
1157	 *
1158	 * Description:
1159	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1160	 *
1161	 ****************************************************************************/
1162	
1163	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1164	{
1165	  FAR struct sg2000_eth_priv_s *priv =
1166	      (FAR struct sg2000_eth_priv_s *)dev;
1167	  uint32_t v;
1168	
1169	  up_disable_irq(priv->irq);
1170	
1171	  /* Stop TX DMA */
1172	
1173	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1174	  putreg32(v & ~DMA_TX_ST,
1175	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1176	
1177	  /* Stop RX DMA */
1178	
1179	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1180	  putreg32(v & ~DMA_RX_SR,
1181	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1182	
1183	  /* Disable MAC TX/RX */
1184	
1185	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1186	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1187	           priv->gmac_base + GMAC_CONFIG);
1188	
1189	  netdev_lower_carrier_off(dev);
1190	
1191	  ninfo("netdriver_ifdown: interface down\n");
1192	
1193	  return OK;
1194	}
1195	
1196	/****************************************************************************
1197	 * Name: netdriver_transmit
1198	 *
1199	 * Description:
1200	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1201	 *   The driver takes ownership of the netpkt and MUST free it after TX
1202	 *   completion (or on error).
1203	 *
1204	 *   Returned Value:
1205	 *     OK on success (pkt queued for TX); negated errno on failure.
1206	 *
1207	 ****************************************************************************/
1208	
1209	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1210	                               FAR netpkt_t *pkt)
1211	{
1212	  FAR struct sg2000_eth_priv_s *priv =
1213	      (FAR struct sg2000_eth_priv_s *)dev;
1214	  unsigned int len = netpkt_getdatalen(dev, pkt);
1215	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1216	  const uint8_t *data;
1217	  int ret;
1218	
1219	  syslog(LOG_INFO, "sg2000_eth: TX called len=%u\n", len);
1220	
1221	  if (len > SG2000_ETH_BUFSIZE)
1222	    {
1223	      nerr("ERROR: TX packet too large: %u\n", len);
1224	      netpkt_free(dev, pkt, NETPKT_TX);
1225	      return -E2BIG;
1226	    }
1227	
1228	  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */
1229	
1230	  if (netpkt_is_fragmented(pkt))
1231	    {
1232	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1233	      data = tmp_buf;
1234	    }
1235	  else
1236	    {
1237	      data = netpkt_getdata(dev, pkt);
1238	      if (!data)
1239	        {
1240	          nerr("ERROR: netpkt_getdata returned NULL\n");
1241	          netpkt_free(dev, pkt, NETPKT_TX);
1242	          return -EINVAL;
1243	        }
1244	    }
1245	
1246	  /* Send via DMA */
1247	
1248	  ret = hw_transmit(priv, data, len);
1249	  if (ret < 0)
1250	    {
1251	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1252	      netpkt_free(dev, pkt, NETPKT_TX);
1253	      return ret;
1254	    }
1255	
1256	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1257	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1258	   */
1259	
1260	  {
1261	    irqstate_t flags = up_irq_save();
1262	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1263	
1264	    priv->tx_pkt[slot] = pkt;
1265	    up_irq_restore(flags);
1266	  }
1267	
1268	  return OK;
1269	}
1270	
1271	/****************************************************************************
1272	 * Name: netdriver_receive
1273	 *
1274	 * Description:
1275	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1276	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1277	 *   NULL if no more packets are available.
1278	 *
1279	 *   Returned Value:
1280	 *     A netpkt_t * containing the received packet, or NULL.
1281	 *
1282	 ****************************************************************************/
1283	
1284	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1285	{
1286	  FAR struct sg2000_eth_priv_s *priv =
1287	      (FAR struct sg2000_eth_priv_s *)dev;
1288	  FAR netpkt_t *pkt = NULL;
1289	  struct sg2000_dma_desc_s *desc;
1290	  uint32_t status;
1291	  int frame_len;
1292	  int ret;
1293	
1294	  /* Check if there is a completed RX descriptor */
1295	
1296	  desc = &priv->rx_desc[priv->rx_cur];
1297	  if (desc->des0 & DESC_OWN)
1298	    {
1299	      /* DMA still owns it, no packet ready yet.
1300	       * This can happen if rxready was signaled for a previous packet
1301	       * that was already consumed, or in edge cases.
1302	       */
1303	
1304	      return NULL;
1305	    }
1306	
1307	  status = desc->des0;
1308	
1309	  /* Check for errors */
1310	
1311	  if (status & RX_DESC_ES)
1312	    {
1313	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1314	      goto refill;
1315	    }
1316	
1317	  /* Get frame length (includes FCS which we strip) */
1318	
1319	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - ETH_FCSSLEN;
1320	
1321	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1322	    {
1323	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1324	      goto refill;
1325	    }
1326	
1327	  /* Allocate a netpkt for the received data */
1328	
1329	  pkt = netpkt_alloc(dev, NETPKT_RX);
1330	  if (!pkt)
1331	    {
1332	      nerr("ERROR: netpkt_alloc failed\n");
1333	      goto refill;
1334	    }
1335	
1336	  /* Copy data from DMA RX buffer into the netpkt */
1337	
1338	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1339	  if (ret < 0)
1340	    {
1341	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1342	      netpkt_free(dev, pkt, NETPKT_RX);
1343	      goto refill;
1344	    }
1345	
1346	  ninfo("RX packet: %d bytes\n", frame_len);
1347	
1348	refill:
1349	  /* Return the descriptor to DMA (set OWN=1) */
1350	
1351	  desc->des0 = DESC_OWN;
1352	  desc->des1 = RX_BUF_SIZE;
1353	
1354	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1355	  rx_doorbell(priv);
1356	
1357	  return pkt;
1358	}
