1366	static const struct netdev_ops_s g_ops =
1367	{
1368	  netdriver_ifup,     /* ifup */
1369	  netdriver_ifdown,   /* ifdown */
1370	  netdriver_transmit, /* transmit */
1371	  netdriver_receive   /* receive */
1372	  /* addmac, rmmac, ioctl, reclaim are not implemented for this simple
1373	   * Ethernet MAC driver.  They are only required for Wi-Fi or advanced
1374	   * filtering scenarios.
