1382	/****************************************************************************
1383	 * Name: sg2000_eth_initialize
1384	 *
1385	 * Description:
1386	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1387	 *   network stack as a netdev_lowerhalf_s device.
1388	 *
1389	 *   Called from board_late_initialize() during system bringup.
1390	 *
1391	 ****************************************************************************/
1392	
1393	int sg2000_eth_initialize(void)
1394	{
1395	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1396	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1397	  int ret;
1398	
1399	  if (g_eth_initialized)
1400	    {
1401	      ninfo("SG2000 Ethernet driver already initialized\n");
1402	      return OK;
1403	    }
1404	
1405	  memset(priv, 0, sizeof(*priv));
1406	  priv->gmac_base = SG2000_GMAC_BASE;
1407	  priv->phy_base = SG2000_EPHY_BASE;
1408	  priv->phy_top = SG2000_EPHY_TOP;
1409	
1410	  /* Set a test MAC address (should be replaced with eFuse/OTP value) */
1411	
1412	  priv->mac_addr[0] = 0x02;
1413	  priv->mac_addr[1] = 0x00;
1414	  priv->mac_addr[2] = 0x00;
1415	  priv->mac_addr[3] = 0x00;
1416	  priv->mac_addr[4] = 0x00;
1417	  priv->mac_addr[5] = 0x01;
1418	
1419	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1420	         IFHWADDRLEN);
1421	
1422	  dev->quota[NETPKT_TX] = TX_RING_SIZE / 2;
1423	  dev->quota[NETPKT_RX] = RX_RING_SIZE / 2;
1424	  dev->ops              = &g_ops;
1425	
1426	  priv->irq = SG2000_IRQ_GMAC;
1427	
1428	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1429	  if (ret < 0)
1430	    {
1431	      nerr("ERROR: netdev_lower_register failed: %d\n", ret);
1432	      return ret;
1433	    }
1434	
1435	  netdev_lower_carrier_off(dev);
1436	  g_eth_initialized = true;
1437	  ninfo("SG2000 Ethernet driver registered as eth0 (lowerhalf)\n");
1438	
1439	  gmac_clock_enable();
1440	
1441	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1442	  if (ret < 0)
1443	    {
1444	      nerr("ERROR: irq_attach failed: %d\n", ret);
1445	      return OK;
1446	    }
1447	
1448	  up_enable_irq(priv->irq);
1449	  ninfo("IRQ %d enabled\n", priv->irq);
1450	
1451	  return OK;
1452	}
