228	void dwmac_dma_flush_tx_fifo(void __iomem *ioaddr)
229	{
230		u32 csr6 = readl(ioaddr + DMA_CONTROL);
231		writel((csr6 | DMA_CONTROL_FTF), ioaddr + DMA_CONTROL);
232	
233		do {} while ((readl(ioaddr + DMA_CONTROL) & DMA_CONTROL_FTF));
234	}
