280	  putreg32(0x0001, phy_top + 0x04);
281	  putreg32(0x0000, phy_base + 0x7c);
282	
283	  putreg32(0x0500, phy_base + 0x7c);
284	  putreg32(0x5a5a, phy_base + 0x64);
285	  putreg32(0x0000, phy_base + 0x54);
286	  putreg32(0x0bb0, phy_base + 0x58);
287	  putreg32(0x0c10, phy_base + 0x5c);
288	  putreg32(0x0003, phy_base + 0x68);
289	  putreg32(0x0000, phy_base + 0x54);
290	
291	  putreg32(0x1000, phy_base + 0x7c);
292	  ephy_write_seq(phy_base, page16_100baset,
293	                 sizeof(page16_100baset) / sizeof(page16_100baset[0]));
294	
295	  putreg32(0x1100, phy_base + 0x7c);
296	  ephy_write_seq(phy_base, page17_100baset,
297	                 sizeof(page17_100baset) / sizeof(page17_100baset[0]));
298	
299	  putreg32(0x0500, phy_base + 0x7c);
300	  putreg32(getreg32(phy_base + 0x40) | 0x0001, phy_base + 0x40);
301	  putreg32(getreg32(phy_base + 0x4c) | 0x0820, phy_base + 0x4c);
302	
303	  putreg32(0x0a00, phy_base + 0x7c);
304	  ephy_write_seq(phy_base, page10_link_pulse,
305	                 sizeof(page10_link_pulse) / sizeof(page10_link_pulse[0]));
306	
307	  putreg32(0x0b00, phy_base + 0x7c);
308	  ephy_write_seq(phy_base, page11_tp_idle,
309	                 sizeof(page11_tp_idle) / sizeof(page11_tp_idle[0]));
310	
311	  putreg32(0x0d00, phy_base + 0x7c);
312	  ephy_write_seq(phy_base, page13_10baset,
313	                 sizeof(page13_10baset) / sizeof(page13_10baset[0]));
314	
315	  putreg32(0x0e00, phy_base + 0x7c);
316	  ephy_write_seq(phy_base, page14_10baset,
317	                 sizeof(page14_10baset) / sizeof(page14_10baset[0]));
318	
319	  putreg32(0x0f00, phy_base + 0x7c);
320	  ephy_write_seq(phy_base, page15_10baset,
321	                 sizeof(page15_10baset) / sizeof(page15_10baset[0]));
322	
323	  putreg32(0x1000, phy_base + 0x7c);
324	  ephy_write_seq(phy_base, page16_10baset,
325	                 sizeof(page16_10baset) / sizeof(page16_10baset[0]));
326	
327	  putreg32(0x0100, phy_base + 0x7c);
328	  putreg32(getreg32(phy_base + 0x68) & ~0x0f00, phy_base + 0x68);
329	
330	  putreg32(0x1300, phy_base + 0x7c);
331	  putreg32(0x0012, phy_base + 0x58);
332	  putreg32(0x6848, phy_base + 0x5c);
333	
334	  putreg32(0x1200, phy_base + 0x7c);
335	  ephy_write_seq(phy_base, page18_cv181x,
336	                 sizeof(page18_cv181x) / sizeof(page18_cv181x[0]));
337	
338	  putreg32(0x0000, phy_base + 0x7c);
339	  putreg32(0x090e, phy_top);
340	  putreg32(getreg32(phy_base) | 0x0100, phy_base);
341	}
342	
343	static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
344	{
345	  uint32_t apb_id1;
346	  uint32_t apb_id2;
347	
348	  ephy_led_pinmux();
349	
350	  /* Minimal EPHY init sequence, matches Linux bm_eth_reset_phy() in
351	   * dwmac-cvitek.c and U-Boot cv181x_ephy_id_init() in board.c.
352	   * This ONLY releases resets and programs the PHY ID — it does NOT
353	   * run the full analog tuning sequence.  The full tuning (which
354	   * accesses internal pages and starts auto-negotiation) must run
355	   * AFTER the MDIO interface is confirmed operational, just as
356	   * Linux does in cv182xa_phy_config_init() -> config_init callback.
357	   */
358	
359	  /* Select APB interface to access EPHY registers */
360	
361	  putreg32(0x0001, phy_top + 0x4);
362	
363	  /* Release shutdown */
364	
365	  putreg32(0x0900, phy_top);
366	
367	  /* Release dig_rst_n — enables MII register access via APB */
368	
369	  putreg32(0x0904, phy_top);
370	
371	  /* Switch to Page 5 for ANA init */
372	
373	  putreg32(0x0500, phy_base + 0x7c);
374	
375	  /* ANA_PD (power-down release) */
376	
377	  putreg32(0x0c00, phy_base + 0x40);
378	
379	  /* ANA_EN */
380	
381	  putreg32(0x0c7e, phy_base + 0x40);
382	  up_mdelay(1);
383	
384	  /* Release ana_rst_n */
385	
386	  putreg32(0x0906, phy_top);
387	  putreg32(0x0500, phy_base + 0x7c);
388	
389	  /* Program PHY ID into EPHY registers (so MDIO can discover it) */
390	
391	  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
392	  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */
393	
394	  apb_id1 = getreg32(phy_base + 0x08) & 0xffff;
395	  apb_id2 = getreg32(phy_base + 0x0c) & 0xffff;
396	  syslog(LOG_INFO, "sg2000_eth: EPHY APB PHYID=0x%04" PRIX32
397	         "%04" PRIX32 "\n", apb_id1, apb_id2);
398	
399	  /* Switch control to MDIO (GMAC) so the DWMAC4 MDIO controller can
400	   * discover and communicate with the PHY.
401	   */
402	
403	  putreg32(0x0000, phy_top + 0x4);
404	  up_mdelay(10);
405	
406	  syslog(LOG_INFO, "sg2000_eth: EPHY init done top=0x%08" PRIX32
407	         " sel=0x%08" PRIX32 "\n",
408	         getreg32(phy_top), getreg32(phy_top + 0x4));
409	}
410	
411	/****************************************************************************
412	 * Name: ephy_full_tuning
413	 *
414	 * Description:
415	 *   Run the full CV182XA analog tuning sequence via APB, then switch back
416	 *   to MDIO control.  Matches Linux cv182xa_phy_config_init().
417	 *   MUST be called AFTER MDIO is confirmed operational, as it accesses
418	 *   internal pages and starts auto-negotiation which can interfere with
419	 *   MDIO if run before the MDIO interface is active.
420	 *
421	 ****************************************************************************/
422	
423	static void ephy_full_tuning(uintptr_t phy_base, uintptr_t phy_top)
424	{
425	  /* ephy_full_analog_init expects APB mode; caller ensures MDIO is working
426	   * before we switch to APB for tuning.
427	   */
428	
429	  putreg32(0x0001, phy_top + 0x4);
430	  ephy_full_analog_init(phy_base, phy_top);
431	
432	  /* ephy_full_analog_init ends with:
433	   *   page 0 + autoneg start (0x090e) + force full-duplex
434	   * Switch control back to MDIO so the GMAC can manage the PHY.
435	   */
436	
437	  putreg32(0x0000, phy_top + 0x4);
438	  up_mdelay(10);
439	
440	  syslog(LOG_INFO, "sg2000_eth: EPHY full tuning done, top=0x%08" PRIX32
441	         " sel=0x%08" PRIX32 "\n",
442	         getreg32(phy_top), getreg32(phy_top + 0x4));
443	}
444	
445	/* SG2000/CV181x uses the TRM (Technical Reference Manual) Chapter 18
446	 * legacy GMAC MDIO layout at offsets 0x10/0x14.  The standard DWMAC4
447	 * MDIO controller at 0x200/0x204 is not functional on this silicon.
448	 */
449	
450	static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
451	{
452	  uint32_t cmd;
453	  int timeout = 10000;
454	
455	  do
456	    {
457	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
458	            LEGACY_GMAC_MDIO_BUSY))
459	        {
460	          break;
461	        }
462	
463	      up_udelay(1);
464	    }
465	  while (--timeout > 0);
466	
467	  if (timeout <= 0)
468	    {
469	      return 0xffff;
470	    }
471	
472	  putreg32(0, gmac_base + LEGACY_GMAC_MDIO_DATA);
473	
474	  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
475	        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
476	        LEGACY_GMAC_MDIO_CR_250_300M | LEGACY_GMAC_MDIO_BUSY;
477	  putreg32(cmd, gmac_base + LEGACY_GMAC_MDIO_ADDR);
478	
479	  timeout = 10000;
480	  do
481	    {
482	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
483	            LEGACY_GMAC_MDIO_BUSY))
484	        {
485	          return getreg32(gmac_base + LEGACY_GMAC_MDIO_DATA) & 0xffff;
486	        }
487	
488	      up_udelay(1);
489	    }
490	  while (--timeout > 0);
491	
492	  return 0xffff;
493	}
494	
495	static void mdio_write(uintptr_t gmac_base, int phy_addr, int reg,
496	                       uint16_t data)
497	{
498	  uint32_t cmd;
499	  int timeout = 10000;
500	
501	  putreg32(data, gmac_base + LEGACY_GMAC_MDIO_DATA);
502	  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
503	        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
504	        LEGACY_GMAC_MDIO_CR_250_300M | LEGACY_GMAC_MDIO_WRITE |
505	        LEGACY_GMAC_MDIO_BUSY;
506	  putreg32(cmd, gmac_base + LEGACY_GMAC_MDIO_ADDR);
507	
508	  do
509	    {
510	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
511	            LEGACY_GMAC_MDIO_BUSY))
512	        {
513	          break;
514	        }
515	
516	      up_udelay(1);
517	    }
518	  while (--timeout > 0);
519	}
520	
521	static int mdio_verify_phy(uintptr_t gmac_base)
522	{
523	  uint16_t id1 = mdio_read(gmac_base, 0, 2);
524	  uint16_t id2 = mdio_read(gmac_base, 0, 3);
525	  uint32_t phy_id = ((uint32_t)id1 << 16) | id2;
526	
527	  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO probe phy_id=0x%08"
528	         PRIX32 "\n", phy_id);
529	
530	  if (id1 == 0xffff || id2 == 0xffff)
531	    {
532	      syslog(LOG_ERR, "sg2000_eth: TRM legacy MDIO timeout reading "
533	             "PHY ID\n");
534	      return -ENODEV;
535	    }
536	
537	  if (phy_id != CVITEK_PHY_ID)
538	    {
539	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
540	             " (expected 0x%08" PRIX32 ")\n", phy_id,
541	             (uint32_t)CVITEK_PHY_ID);
542	    }
543	
544	  return OK;
545	}
