810	 ****************************************************************************/
811	
812	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
813	{
814	  uint32_t tail = priv->tx_desc_phys +
815	                  priv->tx_cur * sizeof(struct sg2000_dma_desc_s);
816	
817	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_END_ADDR);
818	}
819	
820	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
821	{
822	  uint32_t tail = priv->rx_desc_phys +
823	                  priv->rx_cur * sizeof(struct sg2000_dma_desc_s);
824	
825	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_END_ADDR);
826	}
827	
828	/****************************************************************************
829	 * Private Functions - Hardware Transmit
830	 ****************************************************************************/
831	
832	static int hw_transmit(struct sg2000_eth_priv_s *priv,
833	                       const uint8_t *data, int len)
834	{
835	  unsigned int idx = priv->tx_cur;
836	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
837	  irqstate_t flags;
838	
839	  /* Check if the ring is full */
840	
841	  if (desc->des0 & DESC_OWN)
842	    {
843	      return -EBUSY;
844	    }
845	
846	  /* Copy data to DMA TX buffer */
847	
848	  memcpy(priv->tx_buf[idx], data, len);
849	
850	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
851	  desc->des1 = len;
852	
853	  /* OWN | First Segment | Last Segment | Interrupt on Completion */
854	
855	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
856	               (len & RX_DESC_FL_MASK);
857	
858	  flags = up_irq_save();
859	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
860	
861	  /* Memory barrier: ensure descriptor is visible to DMA engine */
862	
863	  __asm__ volatile ("fence w,w" ::: "memory");
864	
865	  tx_doorbell(priv);
866	  up_irq_restore(flags);
867	
868	  return 0;
869	}
870	
871	/****************************************************************************
872	 * Private Functions - TX Cleanup (called from ISR on TX complete)
873	 ****************************************************************************/
874	
875	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
876	{
877	  irqstate_t flags = up_irq_save();
878	
879	  while (priv->tx_dirty != priv->tx_cur)
880	    {
881	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
882	
883	      if (desc->des0 & DESC_OWN)
884	        {
885	          /* Still owned by DMA, stop */
886	
887	          break;
888	        }
889	
890	      /* Free the netpkt if we have one tracked for this slot */
891	
892	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
893	        {
894	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
895	          priv->tx_pkt[priv->tx_dirty] = NULL;
896	
897	          /* Notify upper half that TX is done */
898	
899	          netdev_lower_txdone(&priv->dev);
900	        }
901	
902	      /* Move to next descriptor */
903	
904	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
905	    }
906	
907	  up_irq_restore(flags);
908	}
909	
910	/****************************************************************************
911	 * Private Functions - ISR
912	 ****************************************************************************/
913	
914	static int sg2000_eth_isr(int irq, void *context, void *arg)
915	{
916	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
917	  uintptr_t base = priv->gmac_base;
918	  uintptr_t dma = base + DMA_CHAN_BASE;
919	  uint32_t status;
920	  uint32_t intr_en;
921	  uint32_t mac;
922	
923	  /* Clear MAC interrupts */
924	
925	  mac = getreg32(base + GMAC_INT_STATUS);
926	  if (mac)
927	    {
928	      putreg32(mac, base + GMAC_INT_STATUS);
929	    }
930	
931	  /* Read DMA channel status (only enabled interrupts) */
932	
933	  intr_en = getreg32(dma + DMA_CHAN_INTR_ENA);
934	  status = getreg32(dma + DMA_CHAN_STATUS) & intr_en;
935	
936	  if (!status)
937	    {
938	      return OK;
939	    }
940	
941	  /* Write-1-to-clear the status bits */
942	
943	  putreg32(status, dma + DMA_CHAN_STATUS);
944	
945	  if (status & DMA_STATUS_NIS)
946	    {
947	      /* Normal interrupt */
948	
949	      if (status & DMA_STATUS_RI)
950	        {
951	          /* RX complete: notify upper half that packets are ready.
952	           * The upper half will call our receive() callback to get them.
953	           */
954	
955	          netdev_lower_rxready(&priv->dev);
956	        }
957	
958	      if (status & DMA_STATUS_TI)
959	        {
960	          /* TX complete: cleanup descriptors and notify upper half */
961	
962	          tx_cleanup(priv);
963	        }
964	    }
965	
966	  if (status & DMA_STATUS_AIS)
967	    {
968	      /* Abnormal interrupt - handled silently in ISR context */
969	
970	  return OK;
971	}
972	
973	/****************************************************************************
974	 * Name: netdriver_ifup
975	 *
976	 * Description:
977	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
978	 *
979	 ****************************************************************************/
980	
981	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
982	{
983	  FAR struct sg2000_eth_priv_s *priv =
984	      (FAR struct sg2000_eth_priv_s *)dev;
985	  int ret;
986	
987	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
988	
989	  /* Ensure GMAC clocks and resets are configured */
990	
991	  gmac_clock_enable();
992	
993	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
994	
995	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
996	
997	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
998	  up_mdelay(10);
999	
1000	  ret = mdio_verify_phy(priv->gmac_base);
1001	  if (ret < 0)
1002	    {
1003	      nerr("ERROR: TRM legacy MDIO PHY not responding: %d\n", ret);
1004	      return ret;
1005	    }
1006	
1007	  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO operational "
1008	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1009	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_ADDR),
1010	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_DATA));
1011	
1012	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1013	
1014	  ret = phy_config_init(priv);
1015	  if (ret < 0)
1016	    {
1017	      nerr("ERROR: PHY init failed: %d\n", ret);
1018	      return ret;
1019	    }
1020	
1021	  ret = dma_soft_reset(priv->gmac_base);
1022	  if (ret < 0)
1023	    {
1024	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1025	             "diagnostics: %d\n", ret);
1026	      return ret;
1027	    }
1028	
1029	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1030	    {
1031	      ret = alloc_dma(priv);
1032	      if (ret < 0)
1033	        {
1034	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1035	          return ret;
1036	        }
1037	    }
1038	
1039	  init_desc_and_dma(priv);
1040	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1041	  start_mac_and_dma(priv);
1042	  rx_doorbell(priv);
1043	
1044	  up_enable_irq(priv->irq);
1045	  netdev_lower_carrier_on(dev);
1046	
1047	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1048	         priv->speed, priv->duplex ? "Full" : "Half");
1049	
1050	  return OK;
1051	}
