1053	/****************************************************************************
1054	 * Name: netdriver_ifdown
1055	 *
1056	 * Description:
1057	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1058	 *
1059	 ****************************************************************************/
1060	
1061	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1062	{
1063	  FAR struct sg2000_eth_priv_s *priv =
1064	      (FAR struct sg2000_eth_priv_s *)dev;
1065	  uint32_t v;
1066	
1067	  up_disable_irq(priv->irq);
1068	
1069	  /* Stop TX DMA */
1070	
1071	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1072	  putreg32(v & ~DMA_TX_ST,
1073	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1074	
1075	  /* Stop RX DMA */
1076	
1077	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1078	  putreg32(v & ~DMA_RX_SR,
1079	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1080	
1081	  /* Disable MAC TX/RX */
1082	
1083	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1084	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1085	           priv->gmac_base + GMAC_CONFIG);
1086	
1087	  netdev_lower_carrier_off(dev);
1088	
1089	  ninfo("netdriver_ifdown: interface down\n");
1090	
1091	  return OK;
1092	}
