1094	/****************************************************************************
1095	 * Name: netdriver_transmit
1096	 *
1097	 * Description:
1098	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1099	 *   The driver takes ownership of the netpkt and MUST free it after TX
1100	 *   completion (or on error).
1101	 *
1102	 *   Returned Value:
1103	 *     OK on success (pkt queued for TX); negated errno on failure.
1104	 *
1105	 ****************************************************************************/
1106	
1107	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1108	                               FAR netpkt_t *pkt)
1109	{
1110	  FAR struct sg2000_eth_priv_s *priv =
1111	      (FAR struct sg2000_eth_priv_s *)dev;
1112	  unsigned int len = netpkt_getdatalen(dev, pkt);
1113	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1114	  const uint8_t *data;
1115	  int ret;
1116	
1117	  if (len > SG2000_ETH_BUFSIZE)
1118	    {
1119	      nerr("ERROR: TX packet too large: %u\n", len);
1120	      netpkt_free(dev, pkt, NETPKT_TX);
1121	      return -E2BIG;
1122	    }
1123	
1124	  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */
1125	
1126	  if (netpkt_is_fragmented(pkt))
1127	    {
1128	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1129	      data = tmp_buf;
1130	    }
1131	  else
1132	    {
1133	      data = netpkt_getdata(dev, pkt);
1134	      if (!data)
1135	        {
1136	          nerr("ERROR: netpkt_getdata returned NULL\n");
1137	          netpkt_free(dev, pkt, NETPKT_TX);
1138	          return -EINVAL;
1139	        }
1140	    }
1141	
1142	  /* Send via DMA */
1143	
1144	  ret = hw_transmit(priv, data, len);
1145	  if (ret < 0)
1146	    {
1147	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1148	      netpkt_free(dev, pkt, NETPKT_TX);
1149	      return ret;
1150	    }
1151	
1152	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1153	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1154	   */
1155	
1156	  {
1157	    irqstate_t flags = up_irq_save();
1158	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1159	
1160	    priv->tx_pkt[slot] = pkt;
1161	    up_irq_restore(flags);
1162	  }
1163	
1164	  return OK;
1165	}
1166	
1167	/****************************************************************************
1168	 * Name: netdriver_receive
1169	 *
1170	 * Description:
1171	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1172	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1173	 *   NULL if no more packets are available.
1174	 *
1175	 *   Returned Value:
1176	 *     A netpkt_t * containing the received packet, or NULL.
1177	 *
1178	 ****************************************************************************/
1179	
1180	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1181	{
1182	  FAR struct sg2000_eth_priv_s *priv =
1183	      (FAR struct sg2000_eth_priv_s *)dev;
1184	  FAR netpkt_t *pkt = NULL;
1185	  struct sg2000_dma_desc_s *desc;
1186	  uint32_t status;
1187	  int frame_len;
1188	  int ret;
1189	
1190	  /* Check if there is a completed RX descriptor */
1191	
1192	  desc = &priv->rx_desc[priv->rx_cur];
1193	  if (desc->des0 & DESC_OWN)
1194	    {
1195	      /* DMA still owns it, no packet ready yet.
1196	       * This can happen if rxready was signaled for a previous packet
1197	       * that was already consumed, or in edge cases.
1198	       */
1199	
1200	      return NULL;
1201	    }
1202	
1203	  status = desc->des0;
1204	
1205	  /* Check for errors */
1206	
1207	  if (status & RX_DESC_ES)
1208	    {
1209	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1210	      goto refill;
1211	    }
1212	
1213	  /* Get frame length (includes FCS which we strip) */
1214	
1215	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - ETH_FCSSLEN;
1216	
1217	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1218	    {
1219	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1220	      goto refill;
1221	    }
1222	
1223	  /* Allocate a netpkt for the received data */
1224	
1225	  pkt = netpkt_alloc(dev, NETPKT_RX);
1226	  if (!pkt)
1227	    {
1228	      nerr("ERROR: netpkt_alloc failed\n");
1229	      goto refill;
1230	    }
1231	
1232	  /* Copy data from DMA RX buffer into the netpkt */
1233	
1234	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1235	  if (ret < 0)
1236	    {
1237	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1238	      netpkt_free(dev, pkt, NETPKT_RX);
1239	      goto refill;
1240	    }
1241	
1242	refill:
1243	  /* Return the descriptor to DMA (set OWN=1) */
1244	
1245	  desc->des0 = DESC_OWN;
1246	  desc->des1 = RX_BUF_SIZE;
1247	
1248	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1249	  rx_doorbell(priv);
1250	
1251	  return pkt;
1252	}
1253	
1254	/****************************************************************************
1255	 * Private Data - Operations Structure
1256	 *
1257	 * The netdev_ops_s maps our callbacks to the OpenVela lowerhalf API.
1258	 ****************************************************************************/
1259	
1260	static const struct netdev_ops_s g_ops =
1261	{
1262	  netdriver_ifup,     /* ifup */
1263	  netdriver_ifdown,   /* ifdown */
1264	  netdriver_transmit, /* transmit */
1265	  netdriver_receive   /* receive */
1266	  /* addmac, rmmac, ioctl, reclaim are not implemented for this simple
1267	   * Ethernet MAC driver.  They are only required for Wi-Fi or advanced
1268	   * filtering scenarios.
1269	   */
1270	};
1271	
