1316	  dev->quota[NETPKT_TX] = TX_RING_SIZE / 2;
1317	  dev->quota[NETPKT_RX] = RX_RING_SIZE / 2;
1318	  dev->ops              = &g_ops;
1319	
1320	  priv->irq = SG2000_IRQ_GMAC;
