713	   */
714	
715	  for (i = 0; i < TX_RING_SIZE; i++)
716	    {
717	      priv->tx_desc[i].des0 = (i == TX_RING_SIZE - 1) ? TX_DESC_TER : 0;
718	      priv->tx_desc[i].des1 = 0;
