985	      putreg32(mac, base + GMAC_INT_STATUS);
986	    }
987	
988	  /* Read DMA Status (CSR5 at 0x1014) */
989	
990	  status = getreg32(base + DMA_STATUS);
991	
992	  if (!status)
993	    {
994	      return OK;
995	    }
996	
997	  /* Write-1-to-clear the status bits (CSR5 bits 0-16 are W1C) */
998	
999	  putreg32(status & DMA_STATUS_W1C_MASK, base + DMA_STATUS);
1000	
1001	  if (status & DMA_STATUS_NIS)
1002	    {
1003	      /* Normal interrupt */
1004	
1005	      if (status & DMA_STATUS_RI)
